m_audio_snd[N]->write(0);

	// WR is asserted for 3 cycles
	m_walk_timer[N]->adjust(attotime::from_ticks(3, m_maincpu->clock()), N);

m_audio_snd[N]->write(0);

	// WR is asserted for 3 cycles
	m_walk_timer[N]->adjust(attotime::from_ticks(3, m_maincpu->clock()), N);

data &= 1;

	switch (offset)
	{
		// death
		case 0:
			m_audiocpu->set_input_line(0, data ? ASSERT_LINE : CLEAR_LINE);
			break;

		// get coin, ice
		case 1: case 2:
		{
			const uint8_t mask = 1 << (offset - 1);
			m_soundlatch[3]->write((m_soundlatch[3]->read() & ~mask) | (data ? mask : 0));
			break;
		}

		// crab, turtle, fly, coin
		case 3: case 4: case 5: case 6:
		{
			const uint8_t mask = 1 << (offset - 3);
			m_soundlatch[1]->write((m_soundlatch[1]->read() & ~mask) | (data ? mask : 0));
			break;
		}

		// skid
		case 7:
			m_audio_snd[2]->write(data ^ 1);
			break;
	}

if (!machine().side_effects_disabled())
	{
		// retry_access() forces the MCU to catch up before Z80 does the read
		if (!m_z80_sync)
			m_maincpu->retry_access();

		m_z80_sync = !m_z80_sync;
	}

	const uint8_t p2 = m_soundlatch[2]->read();

	if (BIT(p2, 7))
		return m_soundlatch[0]->read();
	else
		return m_soundrom[(p2 & 0x0f) << 8 | offset];

for (int i = 0; i < 2; i++)
		m_walk_timer[i] = timer_alloc("mario_state.walk_off");

	// Hack to bootstrap MCU program into external MB1
	uint8_t *SND = memregion("audiocpu")->base();

	SND[0x0000] = 0xf5; // sel mb1
	SND[0x0001] = 0x04; // jmp 0
	SND[0x0002] = 0x00;

m_bg_tilemap = &machine().tilemap().create(
			*m_gfxdecode, tilemap_get_info_delegate(*this, FUNC(mario_state::get_bg_tile_info)), TILEMAP_SCAN_ROWS,
			8, 8, 32, 32);

	m_gfxdecode->gfx(0)->set_granularity(8);

	save_item(NAME(m_gfx_bank));
	save_item(NAME(m_palette_bank));

int code = m_videoram[tile_index] + 256 * m_gfx_bank;
	int color = 8 + (m_videoram[tile_index] >> 5) + 16 * m_palette_bank;

	tileinfo.set(0, code, color, 0);

m_bg_tilemap->draw(screen, bitmap, cliprect, 0, 0);
	draw_sprites(bitmap, cliprect);

	return 0;

const uint8_t flip = flip_screen() ? 0xff : 0;
	int offs = 0;

	while (offs != m_spriteram.bytes())
	{
		if (m_spriteram[offs])
		{
			// from schematics...
			int y = (m_spriteram[offs + 0] + (flip ? 0xf7 : 0xf9) + 1) & 0xff;
			int x = m_spriteram[offs + 3];
			// sprite will be drawn if (y + scanline) & 0xF0 = 0xF0
			y = 240 - y; // logical screen position

			y ^= flip; // physical screen location
			x ^= flip; // physical screen location

			int code = m_spriteram[offs + 2];
			int color = (m_spriteram[offs + 1] & 0x0f) + 16 * m_palette_bank;
			int flipx = (m_spriteram[offs + 1] & 0x80);
			int flipy = (m_spriteram[offs + 1] & 0x40);

			if (flip)
			{
				y -= 14;
				x -= 7;
				flipx = !flipx;
				flipy = !flipy;
			}
			else
			{
				y += 1;
				x -= 8;
			}

			m_gfxdecode->gfx(1)->transpen(bitmap, cliprect,
					code,
					color,
					flipx, flipy,
					x, y, 0);
		}

		offs += 4;
	}

uint8_t const *const color_prom = memregion("proms")->base();

	std::vector<rgb_t> rgb;
	if (monitor == 0)
		compute_res_net_all(rgb, color_prom, mario_decode_info, mario_net_info);
	else
		compute_res_net_all(rgb, color_prom + 256, mario_decode_info, mario_net_info_std);

	m_palette->set_pen_colors(0, rgb);
	m_palette->palette()->normalize_range(0, 255);

rgb.resize(rdi.end - rdi.start + 1);
	for (int i = rdi.start; i <= rdi.end; i++)
	{
		u8 t[3] = {0,0,0};
		for (int j = 0; j < rdi.numcomp; j++)
			for (int k = 0; k < 3; k++)
			{
				int s = rdi.shift[3*j+k];
				if (s>0)
					t[k] = t[k] | ( (prom[i+rdi.offset[3*j+k]]>>s) & rdi.mask[3*j+k]);
				else
					t[k] = t[k] | ( (prom[i+rdi.offset[3*j+k]]<<(0-s)) & rdi.mask[3*j+k]);
			}
		u8 r = compute_res_net(t[0], RES_NET_CHAN_RED, di);
		u8 g = compute_res_net(t[1], RES_NET_CHAN_GREEN, di);
		u8 b = compute_res_net(t[2], RES_NET_CHAN_BLUE, di);
		rgb[i-rdi.start] = rgb_t(r,g,b);
	}

double rTotal=0.0;
	double v = 0;

	double vBias = di.rgb[channel].vBias;
	double vOH = di.vOH;
	double vOL = di.vOL;
	double minout = di.rgb[channel].minout;
	double cut = di.rgb[channel].cut;
	double vcc = di.vcc;
	double ttlHRes = 0;
	double rGnd = di.rgb[channel].rGnd;
	u8     OpenCol = di.OpenCol;

	/* Global options */

	switch (di.options & RES_NET_AMP_MASK)
	{
		case RES_NET_AMP_USE_GLOBAL:
			/* just ignore */
			break;
		case RES_NET_AMP_NONE:
			minout = 0.0;
			cut = 0.0;
			break;
		case RES_NET_AMP_DARLINGTON:
			minout = 0.9;
			cut = 0.0;
			break;
		case RES_NET_AMP_EMITTER:
			minout = 0.0;
			cut = 0.7;
			break;
		case RES_NET_AMP_CUSTOM:
			/* Fall through */
			break;
		default:
			fatalerror("compute_res_net: Unknown amplifier type\n");
	}

	switch (di.options & RES_NET_VCC_MASK)
	{
		case RES_NET_VCC_5V:
			vcc = 5.0;
			break;
		case RES_NET_VCC_CUSTOM:
			/* Fall through */
			break;
		default:
			fatalerror("compute_res_net: Unknown vcc type\n");
	}

	switch (di.options & RES_NET_VBIAS_MASK)
	{
		case RES_NET_VBIAS_USE_GLOBAL:
			/* just ignore */
			break;
		case RES_NET_VBIAS_5V:
			vBias = 5.0;
			break;
		case RES_NET_VBIAS_TTL:
			vBias = TTL_VOH;
			break;
		case RES_NET_VBIAS_CUSTOM:
			/* Fall through */
			break;
		default:
			fatalerror("compute_res_net: Unknown vcc type\n");
	}

	switch (di.options & RES_NET_VIN_MASK)
	{
		case RES_NET_VIN_OPEN_COL:
			OpenCol = 1;
			vOL = TTL_VOL;
			break;
		case RES_NET_VIN_VCC:
			vOL = 0.0;
			vOH = vcc;
			OpenCol = 0;
			break;
		case RES_NET_VIN_TTL_OUT:
			vOL = TTL_VOL;
			vOH = TTL_VOH;
			/* rough estimation from 82s129 (7052) datasheet and from various sources
			 * 1.4k / 30
			 */
			ttlHRes = 50;
			OpenCol = 0;
			break;
		case RES_NET_VIN_CUSTOM:
			/* Fall through */
			break;
		default:
			fatalerror("compute_res_net: Unknown vin type\n");
	}

	/* Per channel options */

	switch (di.rgb[channel].options & RES_NET_AMP_MASK)
	{
		case RES_NET_AMP_USE_GLOBAL:
			/* use global defaults */
			break;
		case RES_NET_AMP_NONE:
			minout = 0.0;
			cut = 0.0;
			break;
		case RES_NET_AMP_DARLINGTON:
			minout = 0.7;
			cut = 0.0;
			break;
		case RES_NET_AMP_EMITTER:
			minout = 0.0;
			cut = 0.7;
			break;
		case RES_NET_AMP_CUSTOM:
			/* Fall through */
			break;
		default:
			fatalerror("compute_res_net: Unknown amplifier type\n");
	}

	switch (di.rgb[channel].options & RES_NET_VBIAS_MASK)
	{
		case RES_NET_VBIAS_USE_GLOBAL:
			/* use global defaults */
			break;
		case RES_NET_VBIAS_5V:
			vBias = 5.0;
			break;
		case RES_NET_VBIAS_TTL:
			vBias = TTL_VOH;
			break;
		case RES_NET_VBIAS_CUSTOM:
			/* Fall through */
			break;
		default:
			fatalerror("compute_res_net: Unknown vcc type\n");
	}

	/* Input impedances */

	switch (di.options & RES_NET_MONITOR_MASK)
	{
		case RES_NET_MONITOR_INVERT:
		case RES_NET_MONITOR_SANYO_EZV20:
			/* Nothing */
			break;
		case RES_NET_MONITOR_ELECTROHOME_G07:
			if (rGnd != 0.0)
				rGnd = rGnd * 5600 / (rGnd + 5600);
			else
				rGnd = 5600;
			break;
	}

	/* compute here - pass a / low inputs */

	for (int i = 0; i < di.rgb[channel].num; i++)
	{
		int level = ((inputs >> i) & 1);
		if (di.rgb[channel].R[i] != 0.0 && !level)
		{
			// There is no difference in the calculation of the "low" input
			// (transistor conducting to ground) between TTL output and
			// open collector output. This is documented explicitly in the
			// code below (no difference if / else.
			if (OpenCol)
			{
				rTotal += 1.0 / di.rgb[channel].R[i];
				v += vOL / di.rgb[channel].R[i];
			}
			else
			{
				rTotal += 1.0 / di.rgb[channel].R[i];
				v += vOL / di.rgb[channel].R[i];
			}
		}
	}

	/* Mix in rbias and rgnd */
	if ( di.rgb[channel].rBias != 0.0 )
	{
		rTotal += 1.0 / di.rgb[channel].rBias;
		v += vBias / di.rgb[channel].rBias;
	}
	if (rGnd != 0.0)
		rTotal += 1.0 / rGnd;

	/* if the resulting voltage after application of all low inputs is
	 * greater than vOH, treat high inputs as open collector/high impedance
	 * There will be now current into/from the TTL gate
	 */

	if ( (di.options & RES_NET_VIN_MASK)==RES_NET_VIN_TTL_OUT)
	{
		if (v / rTotal > vOH)
			OpenCol = 1;
	}

	/* Second pass - high inputs */

	for (int i = 0; i < di.rgb[channel].num; i++)
	{
		int level = ((inputs >> i) & 1);
		if (di.rgb[channel].R[i] != 0.0 && level)
		{
			if (OpenCol)
			{
				rTotal += 0;
				v += 0;
			}
			else
			{
				rTotal += 1.0 / (di.rgb[channel].R[i] + ttlHRes);
				v += vOH / (di.rgb[channel].R[i] + ttlHRes);
			}
		}
	}

	rTotal = 1.0 / rTotal;
	v *= rTotal;
	v = std::max(minout, v - cut);

	switch (di.options & RES_NET_MONITOR_MASK)
	{
		case RES_NET_MONITOR_INVERT:
			v = vcc - v;
			break;
		case RES_NET_MONITOR_SANYO_EZV20:
			v = vcc - v;
			v = std::max(double(0), v-0.7);
			v = std::min(v, vcc - 2 * 0.7);
			v = v / (vcc-1.4);
			v = v * vcc;
			break;
		case RES_NET_MONITOR_ELECTROHOME_G07:
			/* Nothing */
			break;
	}

	return int(v * 255 / vcc + 0.4);
